window.focusApp = {

    _dotNetRef: null,
    _resenhaAtiva: false,

    registerNavigationHandler: function (dotNetRef) {
        window.focusApp._dotNetRef = dotNetRef;
        window.addEventListener('navigate', function (e) {
            const page = e.detail?.page;
            if (page && window.focusApp._dotNetRef) {
                window.focusApp._dotNetRef.invokeMethodAsync('NavigateFromJs', page);
            }
        });

        if (!window.focusApp._globalSearchBound) {
            window.focusApp._globalSearchBound = true;
            document.addEventListener('keydown', function (e) {
                const key = e.key.toLowerCase();
                const ctrlOrCmd = e.ctrlKey || e.metaKey;

                if (ctrlOrCmd && key === 'k') {
                    e.preventDefault();
                    if (window.focusApp._dotNetRef) {
                        window.focusApp._dotNetRef.invokeMethodAsync('ToggleGlobalSearch');
                    }
                    return;
                }

                if (ctrlOrCmd && !e.shiftKey && key === 'n') {
                    e.preventDefault();
                    if (window.focusApp._dotNetRef) {
                        window.focusApp._dotNetRef.invokeMethodAsync('RequestNewTaskShortcut');
                    }
                    return;
                }

                if (ctrlOrCmd && e.shiftKey && key === 'p') {
                    e.preventDefault();
                    if (window.focusApp._dotNetRef) {
                        window.focusApp._dotNetRef.invokeMethodAsync('TogglePomodoroShortcut');
                    }
                    return;
                }
            });
        }
    },

    navigateTo: function (page) {
        window.dispatchEvent(new CustomEvent('navigate', { detail: { page } }));
    },

    playSound: function (type) {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);

        const sounds = {
            'complete': { freq: 880, duration: 0.3 },
            'break': { freq: 660, duration: 0.2 },
            'tick': { freq: 440, duration: 0.05 },
        };

        const s = sounds[type] || sounds['complete'];
        osc.frequency.setValueAtTime(s.freq, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(s.freq * 0.8, ctx.currentTime + s.duration);
        gain.gain.setValueAtTime(0.3, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + s.duration);
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + s.duration);
    },

    focusElement: function (id) {
        const el = document.getElementById(id);
        if (el) el.focus();
    },

    scrollTo: function (id) {
        const el = document.getElementById(id);
        if (el) el.scrollIntoView({ behavior: 'smooth' });
    },

    setThemeVars: function (css) {
        let el = document.getElementById('theme-vars');
        if (!el) {
            el = document.createElement('style');
            el.id = 'theme-vars';
            document.head.appendChild(el);
        }
        el.textContent = css;
    },

    ativarResenha: function () {
        window.focusApp._resenhaAtiva = true;

        const b64 = '';
        const binary = atob(b64);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const blob = new Blob([bytes], { type: 'audio/mp4' });
        const url = URL.createObjectURL(blob);
        const audio = new Audio(url);
        audio.play().catch(() => { });

        const icons = Array.from(document.querySelectorAll('i[class*="fa-"]'));
        const total = icons.length;
        if (total === 0) return;

        const startDelay = 2000;
        const audioDuration = 4940;
        const animWindow = audioDuration - startDelay;

        icons.forEach((icon, idx) => {
            const delay = startDelay + Math.round((idx / total) * animWindow);
            setTimeout(() => {
                if (!window.focusApp._resenhaAtiva) return;
                icon.dataset.originalClass = icon.className;
                icon.className = '';
                icon.textContent = '\uD83D\uDC40';
                icon.style.fontStyle = 'normal';
            }, delay);
        });
    },

    desativarResenha: function () {
        window.focusApp._resenhaAtiva = false;

        const existing = document.getElementById('resenha-midia-overlay');
        if (existing) existing.remove();

        const icons = Array.from(document.querySelectorAll('i'));
        icons.forEach(icon => {
            if (icon.dataset.originalClass) {
                icon.className = icon.dataset.originalClass;
                icon.textContent = '';
                icon.style.fontStyle = '';
                delete icon.dataset.originalClass;
            }
        });
    },

    abrirMidiaResenha: function (dataUrl, mimeType) {
        const existing = document.getElementById('resenha-midia-overlay');
        if (existing) existing.remove();

        const overlay = document.createElement('div');
        overlay.id = 'resenha-midia-overlay';
        overlay.style.cssText = [
            'position:fixed', 'inset:0', 'z-index:99999',
            'background:#000', 'display:flex',
            'align-items:center', 'justify-content:center',
            'cursor:pointer'
        ].join(';');

        const closeBtn = document.createElement('button');
        closeBtn.textContent = '\u2715';
        closeBtn.style.cssText = [
            'position:absolute', 'top:18px', 'right:22px',
            'background:rgba(255,255,255,0.12)', 'color:#fff',
            'border:none', 'border-radius:50%',
            'width:36px', 'height:36px', 'font-size:16px',
            'cursor:pointer', 'z-index:1', 'line-height:1',
            'transition:background 0.2s'
        ].join(';');
        closeBtn.onmouseenter = () => closeBtn.style.background = 'rgba(255,255,255,0.28)';
        closeBtn.onmouseleave = () => closeBtn.style.background = 'rgba(255,255,255,0.12)';

        const isVideo = mimeType.startsWith('video/');
        let media;

        if (isVideo) {
            media = document.createElement('video');
            media.src = dataUrl;
            media.autoplay = true;
            media.loop = true;
            media.controls = false;
            media.style.cssText = 'max-width:100%;max-height:100%;object-fit:contain;';
        } else {
            media = document.createElement('img');
            media.src = dataUrl;
            media.style.cssText = 'max-width:100%;max-height:100%;object-fit:contain;';
        }

        const close = () => {
            if (isVideo) media.pause();
            overlay.remove();
            document.removeEventListener('keydown', escHandler);
        };

        const escHandler = (e) => { if (e.key === 'Escape') close(); };

        closeBtn.onclick = (e) => { e.stopPropagation(); close(); };
        overlay.onclick = close;
        media.onclick = (e) => e.stopPropagation();
        document.addEventListener('keydown', escHandler);

        overlay.appendChild(closeBtn);
        overlay.appendChild(media);
        document.body.appendChild(overlay);

        overlay.requestFullscreen?.().catch(() => { });
    },

    renderFinancaCharts: function (lineLabels, lineSaldos, donutLabels, donutValues) {
        const lineCanvas = document.getElementById('financa-line-chart');
        if (lineCanvas) {
            if (lineCanvas._chartInstance) lineCanvas._chartInstance.destroy();
            lineCanvas._chartInstance = new Chart(lineCanvas, {
                type: 'line',
                data: {
                    labels: lineLabels,
                    datasets: [{
                        label: 'Saldo',
                        data: lineSaldos,
                        borderColor: '#7C6AF7',
                        backgroundColor: 'rgba(124,106,247,0.08)',
                        borderWidth: 2,
                        pointBackgroundColor: '#7C6AF7',
                        pointRadius: 4,
                        tension: 0.4,
                        fill: true
                    }]
                },
                options: {
                    responsive: true,
                    plugins: { legend: { display: false } },
                    scales: {
                        x: { ticks: { color: '#5A5A72', font: { size: 11 } }, grid: { color: 'rgba(255,255,255,0.04)' } },
                        y: { ticks: { color: '#5A5A72', font: { size: 11 } }, grid: { color: 'rgba(255,255,255,0.04)' } }
                    }
                }
            });
        }

        const donutCanvas = document.getElementById('financa-donut-chart');
        if (donutCanvas && donutValues.length > 0) {
            if (donutCanvas._chartInstance) donutCanvas._chartInstance.destroy();
            donutCanvas._chartInstance = new Chart(donutCanvas, {
                type: 'doughnut',
                data: {
                    labels: donutLabels,
                    datasets: [{
                        data: donutValues,
                        backgroundColor: ['#F07070', '#F6C644', '#4ECDC4', '#7C6AF7', '#5DD68E', '#E87CA0', '#9D8FF7', '#F0A070', '#70C0F0'],
                        borderWidth: 0
                    }]
                },
                options: {
                    responsive: true,
                    cutout: '65%',
                    plugins: {
                        legend: {
                            position: 'bottom',
                            labels: { color: '#9090A8', font: { size: 11 }, boxWidth: 10, padding: 10 }
                        }
                    }
                }
            });
        }



    }

};